import "./globals.css";

// Next.js config exports (not React components)
// eslint-disable-next-line react-refresh/only-export-components
export const metadata = {
  title: "MealMate — Meal & Cost Tracker",
  description:
    "Meal, expense and money tracking for shared living, backed by a real double-entry ledger.",
};

// eslint-disable-next-line react-refresh/only-export-components
export const viewport = {
  width: "device-width",
  initialScale: 1,
  viewportFit: "cover",
};

export default function RootLayout({ children }) {
  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        {/* Set theme before paint to avoid flash; mm_theme is the only readable cookie */}
        <script
          dangerouslySetInnerHTML={{
            __html: `(function(){try{var m=document.cookie.match(/mm_theme=(dark|light)/);var t=m?m[1]:(window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');document.documentElement.setAttribute('data-theme',t);}catch(e){}})();`,
          }}
        />
      </head>
      <body>{children}</body>
    </html>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";
import { createPortal } from "react-dom";
import {
 IoChevronBack,
 IoChevronForward,
 IoCalendarOutline,
 IoTimeOutline,
 IoClose,
} from "react-icons/io5";

const DAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];
const MONTHS = [
 "January",
 "February",
 "March",
 "April",
 "May",
 "June",
 "July",
 "August",
 "September",
 "October",
 "November",
 "December",
];

// Minute options are shown in 10-minute steps: 0, 10, 20, 30, 40, 50.
const MINUTE_STEP = 10;
const MINUTE_LIST = Array.from(
 { length: Math.ceil(60 / MINUTE_STEP) },
 (_, i) => i * MINUTE_STEP,
);

// Round an arbitrary minute onto the nearest selectable step (max 50).
function snapMinute(m) {
 return Math.min(Math.round(m / MINUTE_STEP) * MINUTE_STEP, 60 - MINUTE_STEP);
}

function pad(n) {
 return String(n).padStart(2, "0");
}

function to12h(h) {
 if (h === 0) return 12;
 if (h > 12) return h - 12;
 return h;
}

function buildCalendar(year, month) {
 const firstDay = new Date(year, month, 1).getDay();
 const daysInMonth = new Date(year, month + 1, 0).getDate();
 const daysInPrev = new Date(year, month, 0).getDate();
 const cells = [];

 for (let i = firstDay - 1; i >= 0; i--) {
  cells.push({
   day: daysInPrev - i,
   month: month - 1,
   year: month === 0 ? year - 1 : year,
   outside: true,
  });
 }
 for (let d = 1; d <= daysInMonth; d++) {
  cells.push({ day: d, month, year, outside: false });
 }
 const remaining = 42 - cells.length;
 for (let d = 1; d <= remaining; d++) {
  cells.push({
   day: d,
   month: month + 1,
   year: month === 11 ? year + 1 : year,
   outside: true,
  });
 }
 return cells;
}

function parseValue(val) {
 if (!val) return null;
 if (val instanceof Date) {
  return isNaN(val.getTime()) ? null : val;
 }
 if (typeof val === "string") {
  const trimmed = val.trim();
  if (!trimmed) return null;

  if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) {
   const [y, m, d] = trimmed.split("-").map(Number);
   return new Date(y, m - 1, d);
  }

  const timeMatch = trimmed.match(
   /^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(am|pm)?$/i,
  );
  if (timeMatch) {
   let h = parseInt(timeMatch[1], 10);
   const m = parseInt(timeMatch[2], 10);
   const meridiem = timeMatch[4]?.toLowerCase();
   if (meridiem === "pm" && h < 12) h += 12;
   if (meridiem === "am" && h === 12) h = 0;
   const d = new Date();
   d.setHours(h, m, 0, 0);
   return d;
  }
 }
 const d = new Date(val);
 return isNaN(d.getTime()) ? null : d;
}

/**
 * Custom DateTimePicker matching the site theme.
 */
export default function DateTimePicker({
 id,
 value,
 onChange,
 placeholder = "Select date & time",
 showTime = true,
 timeOnly = false,
 minDate,
 maxDate,
 disablePast = false,
 disableFuture = false,
 label,
 disabled = false,
 customTrigger,
 use24h = false,
 isRequired = false,
 isInvalid = false,
 errorMessage,
 size = "md",
}) {
 // Stable fallback id when the caller doesn't provide one. Without this,
 // every DateTimePicker instance in a list would share the same implicit
 // id — which broke label/trigger association and let validation styles
 // appear to leak between instances.
 const autoId = useId();
 const pickerId = id || autoId;

 const today = new Date();
 const parsed = parseValue(value);

 // Normalize boundary dates to avoid local time/midnight offset discrepancies
 const toStartOfDay = (d) => {
  if (!d) return null;
  const date = parseValue(d);
  if (!date) return null;
  return new Date(date.getFullYear(), date.getMonth(), date.getDate(), 0, 0, 0, 0);
 };

 const toEndOfDay = (d) => {
  if (!d) return null;
  const date = parseValue(d);
  if (!date) return null;
  return new Date(date.getFullYear(), date.getMonth(), date.getDate(), 23, 59, 59, 999);
 };

 const todayStart = new Date(today.getFullYear(), today.getMonth(), today.getDate(), 0, 0, 0, 0);
 const todayEnd = new Date(today.getFullYear(), today.getMonth(), today.getDate(), 23, 59, 59, 999);

 let effectiveMin = minDate ? toStartOfDay(minDate) : null;
 if (disablePast) {
  effectiveMin = effectiveMin ? (effectiveMin > todayStart ? effectiveMin : todayStart) : todayStart;
 }

 let effectiveMax = maxDate ? toEndOfDay(maxDate) : null;
 if (disableFuture) {
  effectiveMax = effectiveMax ? (effectiveMax < todayEnd ? effectiveMax : todayEnd) : todayEnd;
 }

 const parsedMinTime =
  (typeof minDate === "string" && !/^\d{4}-\d{2}-\d{2}$/.test(minDate)) ||
  minDate instanceof Date
   ? parseValue(minDate)
   : null;

 const parsedMaxTime =
  (typeof maxDate === "string" && !/^\d{4}-\d{2}-\d{2}$/.test(maxDate)) ||
  maxDate instanceof Date
   ? parseValue(maxDate)
   : null;

 let initialHour = parsed
  ? parsed.getHours()
  : disablePast || timeOnly
   ? today.getHours()
   : 0;
 let initialMinute = parsed ? snapMinute(parsed.getMinutes()) : 0;

 if (!parsed && (disablePast || timeOnly)) {
  const nextStep = Math.ceil(today.getMinutes() / MINUTE_STEP) * MINUTE_STEP;
  if (nextStep >= 60) {
   initialHour = (initialHour + 1) % 24;
   initialMinute = 0;
  } else {
   initialMinute = nextStep;
  }
 }

 const defaultViewDate =
  parsed ||
  (effectiveMax && effectiveMax < today
   ? effectiveMax
   : effectiveMin && effectiveMin > today
    ? effectiveMin
    : today);

 const [open, setOpen] = useState(false);
 const [tab, setTab] = useState(timeOnly ? "time" : "date");
 const [is24h, setIs24h] = useState(use24h);
 const [ampm, setAmpm] = useState(initialHour >= 12 ? "PM" : "AM");
 const [viewYear, setViewYear] = useState(defaultViewDate.getFullYear());
 const [viewMonth, setViewMonth] = useState(defaultViewDate.getMonth());
 const [selectedDate, setSelectedDate] = useState(parsed);
 const [hour, setHour] = useState(initialHour);
 const [minute, setMinute] = useState(initialMinute);
 const [dateView, setDateView] = useState("calendar"); // "calendar", "month", "year"

 const wrapperRef = useRef(null);
 const hourScrollRef = useRef(null);
 const minScrollRef = useRef(null);
 const yearScrollRef = useRef(null);
 const dropdownRef = useRef(null);

 useEffect(() => {
  if (!open) return;
  setDateView("calendar"); // Reset view when opened
  if (timeOnly) {
   setTab("time");
  }
  if (!value && !selectedDate) {
   const defaultDate =
    effectiveMax && effectiveMax < today
     ? effectiveMax
     : effectiveMin && effectiveMin > today
      ? effectiveMin
      : today;
   setViewYear(defaultDate.getFullYear());
   setViewMonth(defaultDate.getMonth());
  }
  const onOutside = (e) => {
   const isInsideWrapper =
    wrapperRef.current && wrapperRef.current.contains(e.target);
   const isInsideDropdown =
    dropdownRef.current && dropdownRef.current.contains(e.target);
   if (!isInsideWrapper && !isInsideDropdown) {
    setOpen(false);
   }
  };
  document.addEventListener("mousedown", onOutside);
  return () => document.removeEventListener("mousedown", onOutside);
 }, [open, timeOnly]);

 // Scroll selected items into view
 useEffect(() => {
  if (tab !== "time") return;
  const ITEM_H = 37;
  if (hourScrollRef.current)
   hourScrollRef.current.scrollTop = hour * ITEM_H - 72;
  if (minScrollRef.current)
   minScrollRef.current.scrollTop =
    (snapMinute(minute) / MINUTE_STEP) * ITEM_H - 72;
 }, [tab, hour, minute]);

 useEffect(() => {
  if (dateView === "year" && yearScrollRef.current) {
   const btn = yearScrollRef.current.querySelector(".active");
   if (btn) {
    const container = yearScrollRef.current;
    container.scrollTop =
     btn.offsetTop - container.offsetHeight / 2 + btn.offsetHeight / 2;
   }
  }
 }, [dateView]);

 // Sync external value changes
 useEffect(() => {
  const p = parseValue(value);
  setSelectedDate(p);
  if (p) {
   setViewYear(p.getFullYear());
   setViewMonth(p.getMonth());
   setHour(p.getHours());
   setMinute(snapMinute(p.getMinutes()));
   setAmpm(p.getHours() >= 12 ? "PM" : "AM");
  }
 }, [value]);

 const emit = (date, h, m) => {
  const baseDate =
   date ||
   selectedDate ||
   (parsedMinTime ? new Date(parsedMinTime) : null) ||
   today;
  const d = new Date(baseDate);
  const snappedM = snapMinute(m);
  d.setHours(h, snappedM, 0, 0);
  setSelectedDate(d);

  if (!showTime && !timeOnly) {
   // Return only the date part YYYY-MM-DD
   const yyyy = d.getFullYear();
   const mm = String(d.getMonth() + 1).padStart(2, "0");
   const dd = String(d.getDate()).padStart(2, "0");
   onChange?.(`${yyyy}-${mm}-${dd}`);
  } else {
   onChange?.(d.toISOString());
  }
 };

 // Convert 12h display hour + ampm → 24h internal hour
 const resolve24h = (displayHour, currentAmpm) => {
  let h = displayHour % 12;
  if (currentAmpm === "PM") h += 12;
  return h;
 };

 const isHourDisabled = (h24, onDate = selectedDate) => {
  const checkDate = onDate || (timeOnly ? today : null);
  const isToday =
   checkDate &&
   checkDate.getDate() === today.getDate() &&
   checkDate.getMonth() === today.getMonth() &&
   checkDate.getFullYear() === today.getFullYear();

  if (disablePast && isToday && h24 < today.getHours()) {
   return true;
  }
  if (disableFuture && isToday && h24 > today.getHours()) {
   return true;
  }

  const isMinDay =
   checkDate &&
   parsedMinTime &&
   checkDate.getDate() === parsedMinTime.getDate() &&
   checkDate.getMonth() === parsedMinTime.getMonth() &&
   checkDate.getFullYear() === parsedMinTime.getFullYear();

  if (isMinDay && h24 < parsedMinTime.getHours()) {
   return true;
  }

  const isMaxDay =
   checkDate &&
   parsedMaxTime &&
   checkDate.getDate() === parsedMaxTime.getDate() &&
   checkDate.getMonth() === parsedMaxTime.getMonth() &&
   checkDate.getFullYear() === parsedMaxTime.getFullYear();

  if (isMaxDay && h24 > parsedMaxTime.getHours()) {
   return true;
  }

  return false;
 };

 const isMinuteDisabled = (m, checkHour = hour, onDate = selectedDate) => {
  const checkDate = onDate || (timeOnly ? today : null);
  const isToday =
   checkDate &&
   checkDate.getDate() === today.getDate() &&
   checkDate.getMonth() === today.getMonth() &&
   checkDate.getFullYear() === today.getFullYear();

  if (
   disablePast &&
   isToday &&
   checkHour === today.getHours() &&
   m < today.getMinutes()
  ) {
   return true;
  }
  if (
   disableFuture &&
   isToday &&
   checkHour === today.getHours() &&
   m > today.getMinutes()
  ) {
   return true;
  }

  const isMinDay =
   onDate &&
   parsedMinTime &&
   onDate.getDate() === parsedMinTime.getDate() &&
   onDate.getMonth() === parsedMinTime.getMonth() &&
   onDate.getFullYear() === parsedMinTime.getFullYear();

  if (
   isMinDay &&
   checkHour === parsedMinTime.getHours() &&
   m < parsedMinTime.getMinutes()
  ) {
   return true;
  }

  const isMaxDay =
   onDate &&
   parsedMaxTime &&
   onDate.getDate() === parsedMaxTime.getDate() &&
   onDate.getMonth() === parsedMaxTime.getMonth() &&
   onDate.getFullYear() === parsedMaxTime.getFullYear();

  if (
   isMaxDay &&
   checkHour === parsedMaxTime.getHours() &&
   m > parsedMaxTime.getMinutes()
  ) {
   return true;
  }

  return false;
 };

 // An hour is only usable when at least one stepped minute is valid for it.
 const hasSelectableMinute = (h24, onDate = selectedDate) =>
  MINUTE_LIST.some((m) => !isMinuteDisabled(m, h24, onDate));

 // First stepped minute (0, 10, …, 50) valid for the given hour/date.
 const firstEnabledMinute = (h24, onDate = selectedDate) => {
  const found = MINUTE_LIST.find((m) => !isMinuteDisabled(m, h24, onDate));
  return found === undefined ? null : found;
 };

 const isPeriodDisabled = (period, onDate = selectedDate) => {
  const startHour = period === "AM" ? 0 : 12;
  for (let h = startHour; h < startHour + 12; h++) {
   if (!isHourDisabled(h, onDate) && hasSelectableMinute(h, onDate)) {
    return false;
   }
  }
  return true;
 };

 // Keep the selected minute on a valid step for the current hour/date —
 // e.g. an externally supplied 10:37 against a 10:35 max, or "now" being
 // 10:57 with disablePast, where no stepped minute fits that hour.
 useEffect(() => {
  if (!showTime && !timeOnly) return;
  if (!isMinuteDisabled(minute, hour, selectedDate)) return;
  const fallback = firstEnabledMinute(hour, selectedDate);
  if (fallback !== null) {
   setMinute(fallback);
   return;
  }
  for (let i = 1; i <= 24; i++) {
   const h = (hour + i) % 24;
   if (isHourDisabled(h, selectedDate)) continue;
   const m = firstEnabledMinute(h, selectedDate);
   if (m !== null) {
    setHour(h);
    setMinute(m);
    setAmpm(h >= 12 ? "PM" : "AM");
    break;
   }
  }
 }, [hour, minute, selectedDate]);

 const selectDay = (cell) => {
  const d = new Date(cell.year, cell.month, cell.day);
  setSelectedDate(d);
  if (!cell.outside) {
   setViewYear(cell.year);
   setViewMonth(cell.month);
  }

  let nextHour = hour;
  let nextMinute = minute;

  if (showTime) {
   nextMinute = snapMinute(nextMinute);
   if (isHourDisabled(nextHour, d) || !hasSelectableMinute(nextHour, d)) {
    for (let h = 0; h < 24; h++) {
     if (!isHourDisabled(h, d) && hasSelectableMinute(h, d)) {
      nextHour = h;
      break;
     }
    }
   }
   if (isMinuteDisabled(nextMinute, nextHour, d)) {
    const fallback = firstEnabledMinute(nextHour, d);
    if (fallback !== null) nextMinute = fallback;
   }
   setHour(nextHour);
   setMinute(nextMinute);
   setAmpm(nextHour >= 12 ? "PM" : "AM");
  }

  if (!showTime) {
   emit(d, nextHour, nextMinute);
   setOpen(false);
  } else {
   setTab("time");
   emit(d, nextHour, nextMinute);
  }
 };

 const confirmTime = () => {
  emit(selectedDate, hour, minute);
  setOpen(false);
 };

 const isDisabledDay = (cell) => {
  if (cell.outside) return true;
  const d = new Date(cell.year, cell.month, cell.day, 0, 0, 0, 0);
  if (effectiveMin && d < effectiveMin) return true;
  if (effectiveMax && d > effectiveMax) return true;
  return false;
 };

 const isMonthDisabled = (monthIndex) => {
  const monthStart = new Date(viewYear, monthIndex, 1, 0, 0, 0, 0);
  const monthEnd = new Date(viewYear, monthIndex + 1, 0, 23, 59, 59, 999);
  if (effectiveMin && monthEnd < effectiveMin) return true;
  if (effectiveMax && monthStart > effectiveMax) return true;
  return false;
 };

 const isYearDisabled = (y) => {
  const yearStart = new Date(y, 0, 1, 0, 0, 0, 0);
  const yearEnd = new Date(y, 11, 31, 23, 59, 59, 999);
  if (effectiveMin && yearEnd < effectiveMin) return true;
  if (effectiveMax && yearStart > effectiveMax) return true;
  return false;
 };

 const isPrevMonthDisabled = () => {
  if (!effectiveMin) return false;
  const prevMonthEnd = new Date(viewYear, viewMonth, 0, 23, 59, 59, 999);
  return prevMonthEnd < effectiveMin;
 };

 const isNextMonthDisabled = () => {
  if (!effectiveMax) return false;
  const nextMonthStart = new Date(viewYear, viewMonth + 1, 1, 0, 0, 0, 0);
  return nextMonthStart > effectiveMax;
 };

 const isToday = (cell) => {
  const d = new Date(cell.year, cell.month, cell.day);
  return (
   d.getDate() === today.getDate() &&
   d.getMonth() === today.getMonth() &&
   d.getFullYear() === today.getFullYear()
  );
 };

 const isSelected = (cell) => {
  if (!selectedDate) return false;
  return (
   cell.day === selectedDate.getDate() &&
   cell.month === selectedDate.getMonth() &&
   cell.year === selectedDate.getFullYear()
  );
 };

 const prevMonth = () => {
  if (isPrevMonthDisabled()) return;
  if (viewMonth === 0) {
   setViewMonth(11);
   setViewYear((y) => y - 1);
  } else setViewMonth((m) => m - 1);
 };

 const nextMonth = () => {
  if (isNextMonthDisabled()) return;
  if (viewMonth === 11) {
   setViewMonth(0);
   setViewYear((y) => y + 1);
  } else setViewMonth((m) => m + 1);
 };

 const displayTime = () => {
  if (is24h) return `${pad(hour)}:${pad(minute)}`;
  return `${pad(to12h(hour))}:${pad(minute)} ${hour >= 12 ? "PM" : "AM"}`;
 };

 const [dropdownPos, setDropdownPos] = useState({
  top: 0,
  left: 0,
  width: 300,
 });
 const triggerRef = useRef(null);

 useEffect(() => {
  if (!open || !triggerRef.current) return;

  const updatePos = () => {
   if (!triggerRef.current) return;
   const rect = triggerRef.current.getBoundingClientRect();
   const scrollY = window.scrollY;
   const scrollX = window.scrollX;

   // Try to get real height if available, fallback to safe estimate
   const dropdownHeight = dropdownRef.current?.offsetHeight || 420;

   // Constrain width to viewport and maximum allowed
   let width = Math.min(340, Math.max(300, rect.width));
   if (width > window.innerWidth - 20) {
    width = window.innerWidth - 20;
   }

   // Default: show below
   let top = rect.bottom + scrollY + 8;
   let left = rect.left + scrollX;

   // Vertical collision check
   const spaceBelow = window.innerHeight - rect.bottom;
   const spaceAbove = rect.top;

   if (spaceBelow < dropdownHeight && spaceAbove > spaceBelow) {
    // Show above if there's more space above than below
    top = rect.top + scrollY - dropdownHeight - 8;
   }

   // Horizontal collision check
   if (left + width > window.innerWidth + scrollX) {
    // Align right edge to viewport right edge
    left = window.innerWidth - width - 10 + scrollX;
   }
   if (left < scrollX + 10) left = scrollX + 10; // Clamp to left edge

   setDropdownPos({ top, left, width });
  };

  // Run once on mount/open
  updatePos();

  // Run again after a tiny delay to catch the real height if it was just rendered
  const timer = setTimeout(updatePos, 0);

  window.addEventListener("scroll", updatePos, true);
  window.addEventListener("resize", updatePos);
  return () => {
   clearTimeout(timer);
   window.removeEventListener("scroll", updatePos, true);
   window.removeEventListener("resize", updatePos);
  };
 }, [open, tab, dateView]);

 const displayValue = () => {
  if (!selectedDate) return null;
  if (timeOnly) {
   return displayTime();
  }
  const dateStr = `${MONTHS[selectedDate.getMonth()].slice(0, 3)} ${selectedDate.getDate()}, ${selectedDate.getFullYear()}`;
  if (!showTime) return dateStr;
  return `${dateStr} ${displayTime()}`;
 };

 const hourList = is24h
  ? Array.from({ length: 24 }, (_, h) => h)
  : Array.from({ length: 12 }, (_, h) => h + 1);

 const cells = buildCalendar(viewYear, viewMonth);

 const dropdownContent = open && (
  <div
   ref={dropdownRef}
   className={["absolute", "[top:var(--inline-top)]", "[left:var(--inline-left)]", "[width:var(--inline-width)]", "[max-width:340px]", "[2147483647]", "[background:var(--bgs)]", "[border:1.5px_solid_var(--bd2)]", "[border-radius:var(--r-lg)]", "[box-shadow:var(--shadow-xl)]", "[overflow:hidden]", "[animation:dtpFadeIn_0.15s_ease-out]"].filter(Boolean).join(" ")} style={{ "--inline-top": `${dropdownPos.top}px`, "--inline-left": `${dropdownPos.left}px`, "--inline-width": `${dropdownPos.width}px` }}
  >
   <style
    dangerouslySetInnerHTML={{
     __html: `
        @keyframes dtpFadeIn {
          from { opacity: 0; transform: translateY(-6px); }
          to  { opacity: 1; transform: translateY(0); }
        }
        .dtp-day-btn {
          width: 36px;
          height: 36px;
          border-radius: 50%;
          border: none;
          background: transparent;
          cursor: pointer;
          font-size: 0.82rem;
          font-weight: 600;
          color: var(--tp);
          transition: background 0.14s, color 0.14s;
          display: flex;
          align-items: center;
          justify-content: center;
        }
        .dtp-day-btn:hover:not(:disabled) {
          background: var(--pale);
          color: var(--p);
        }
        .dtp-day-btn.today {
          border: 1.5px solid var(--p);
          color: var(--p);
        }
        .dtp-day-btn.selected {
          background: var(--p) !important;
          color: var(--bgs) !important;
          font-weight: 800;
        }
        .dtp-day-btn.outside {
          color: var(--tl);
          opacity: 0.45;
        }
        .dtp-day-btn:disabled {
          cursor: not-allowed;
          opacity: 0.3;
        }
        .dtp-time-scroll {
          height: 180px;
          overflow-y: auto;
          scrollbar-width: thin;
          scrollbar-color: var(--p2) var(--bgm);
        }
        .dtp-time-scroll::-webkit-scrollbar {
          width: 5px;
        }
        .dtp-time-scroll::-webkit-scrollbar-track {
          background: var(--bgm);
          border-radius: 999px;
        }
        .dtp-time-scroll::-webkit-scrollbar-thumb {
          background: var(--p2);
          border-radius: 999px;
        }
        .dtp-time-scroll::-webkit-scrollbar-thumb:hover {
          background: var(--p);
        }
        .dtp-time-item {
          height: 37px;
          display: flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
          font-size: 0.95rem;
          font-weight: 600;
          color: var(--ts);
          border-radius: var(--r-sm);
          transition: background 0.12s, color 0.12s;
          user-select: none;
        }
        .dtp-time-item:hover {
          background: var(--pale);
          color: var(--p);
        }
        .dtp-time-item.active {
          background: var(--p);
          color: var(--bgs);
          font-weight: 800;
        }
        .dtp-tab-btn {
          flex: 1;
          padding: 9px 0;
          border: none;
          background: transparent;
          cursor: pointer;
          font-size: 0.8rem;
          font-weight: 700;
          letter-spacing: 0.05em;
          text-transform: uppercase;
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 6px;
          transition: color 0.15s, background 0.15s;
          border-bottom: 2px solid transparent;
        }
        .dtp-tab-btn.active {
          color: var(--p);
          border-bottom-color: var(--p);
        }
        .dtp-tab-btn:not(.active) {
          color: var(--tm);
        }
        .dtp-nav-btn {
          width: 32px;
          height: 32px;
          border: 1.5px solid var(--bd2);
          border-radius: var(--r-sm);
          background: var(--bg);
          display: flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
          color: var(--tm);
          transition: background 0.14s, color 0.14s, border-color 0.14s;
        }
        .dtp-nav-btn:hover {
          background: var(--pale);
          color: var(--p);
          border-color: var(--p);
        }
        .dtp-nav-btn:disabled {
          opacity: 0.25;
          cursor: not-allowed;
          pointer-events: none;
        }
        .dtp-grid-btn:disabled {
          opacity: 0.25;
          cursor: not-allowed;
          pointer-events: none;
        }
        .dtp-time-item.disabled {
          opacity: 0.25;
          cursor: not-allowed;
          pointer-events: none;
        }
        .dtp-ampm-btn:disabled {
          opacity: 0.25;
          cursor: not-allowed;
          pointer-events: none;
        }
        .dtp-format-toggle {
          display: flex;
          border-radius: var(--r-sm);
          overflow: hidden;
          border: 1.5px solid var(--bd2);
        }
        .dtp-format-btn {
          flex: 1;
          padding: 4px 10px;
          border: none;
          background: transparent;
          font-size: 0.72rem;
          font-weight: 800;
          letter-spacing: 0.06em;
          cursor: pointer;
          color: var(--tm);
          transition: background 0.14s, color 0.14s;
        }
        .dtp-format-btn.active {
          background: var(--p);
          color: var(--bgs);
        }
        .dtp-ampm-btn {
          width: 46px;
          padding: 0;
          border: none;
          border-radius: var(--r-sm);
          font-size: 0.82rem;
          font-weight: 800;
          letter-spacing: 0.06em;
          cursor: pointer;
          transition: background 0.14s, color 0.14s;
        }
        .dtp-ampm-btn.active {
          background: var(--p);
          color: var(--bgs);
        }
        .dtp-ampm-btn:not(.active) {
          background: var(--bgm);
          color: var(--tm);
        }
        .dtp-select {
          appearance: none;
          -webkit-appearance: none;
          background-color: var(--bg);
          border: 1.5px solid var(--bd2);
          color: var(--tp);
          font-weight: 700;
          font-size: 0.85rem;
          cursor: pointer;
          outline: none;
          font-family: inherit;
          padding: 4px 22px 4px 8px;
          border-radius: var(--r-sm);
          transition: all 0.15s ease;
          background-image: url("data:image/svg+xml;charset=US-ASCII,%3Csvg%20width%3D%2210%22%20height%3D%226%22%20viewBox%3D%220%200%2010%206%22%20fill%3D%22none%22%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%3E%3Cpath%20d%3D%22M1%201L5%205L9%201%22%20stroke%3D%22%23888888%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22/%3E%3C/svg%3E");
          background-repeat: no-repeat;
          background-position: right 6px center;
        }
        .dtp-select:hover, .dtp-select:focus {
          border-color: var(--p);
          background-color: var(--pale);
        }
        .dtp-select-wrapper {
          display: flex;
          gap: 6px;
          align-items: center;
        }
        .dtp-grid-btn {
          padding: 10px 4px;
          border: 1.5px solid transparent;
          background: var(--bg);
          border-radius: var(--r-sm);
          font-size: 0.85rem;
          font-weight: 700;
          color: var(--ts);
          cursor: pointer;
          transition: all 0.15s;
          display: flex;
          align-items: center;
          justify-content: center;
        }
        .dtp-grid-btn:hover {
          background: var(--pale);
          color: var(--p);
        }
        .dtp-grid-btn.active {
          background: var(--p);
          color: var(--bgs);
          border-color: var(--p);
        }
        .dtp-grid-container {
          display: grid;
          grid-template-columns: repeat(3, 1fr);
          gap: 8px;
          padding: 4px 0;
        }
        .dtp-year-scroll {
          max-height: 250px;
          overflow-y: auto;
          scrollbar-width: thin;
          scrollbar-color: var(--p2) var(--bgm);
          padding-right: 4px;
          border-radius: 15px;
        }
        .dtp-year-scroll::-webkit-scrollbar { width: 5px; }
        .dtp-year-scroll::-webkit-scrollbar-track { background: var(--bgm); border-radius: 999px; }
        .dtp-year-scroll::-webkit-scrollbar-thumb { background: var(--p2); border-radius: 999px; }
      `,
    }}
   />

   {/* Tabs */}
   {showTime && !timeOnly && (
    <div
     className={["flex", "[border-bottom:1.5px_solid_var(--bd)]", "[background:var(--bg)]"].filter(Boolean).join(" ")}
    >
     <button
      type="button"
      className={`dtp-tab-btn ${tab === "date" ? "active" : ""}`}
      onClick={() => setTab("date")}
     >
      <IoCalendarOutline /> Date
     </button>
     <button
      type="button"
      className={`dtp-tab-btn ${tab === "time" ? "active" : ""}`}
      onClick={() => setTab("time")}
     >
      <IoTimeOutline /> Time
     </button>
    </div>
   )}

   {/* Date Panel */}
   {tab === "date" && (
    <div className={["p-4", "[height:340px]", "[overflow:hidden]"].filter(Boolean).join(" ")}>
     {dateView === "calendar" && (
      <>
       {/* Month/Year Nav */}
       <div
        className={["flex", "items-center", "justify-between", "[margin-bottom:14px]"].filter(Boolean).join(" ")}
       >
        <button
         type="button"
         className="dtp-nav-btn"
         disabled={isPrevMonthDisabled()}
         onClick={prevMonth}
        >
         <IoChevronBack className={["[font-size:0.95rem]"].filter(Boolean).join(" ")} />
        </button>

        <div className="dtp-select-wrapper">
         <button
          type="button"
          onClick={() => setDateView("month")}
          
          className="dtp-select [border-radius:8px] [font-size:0.75rem] [padding:8px_24px_8px_12px]"
         >
          {MONTHS[viewMonth].slice(0, 3)}
         </button>
         <button
          type="button"
          onClick={() => setDateView("year")}
          
          className="dtp-select [border-radius:8px] [font-size:0.75rem] [padding:8px_24px_8px_12px]"
         >
          {viewYear}
         </button>
        </div>

        <button
         type="button"
         className="dtp-nav-btn"
         disabled={isNextMonthDisabled()}
         onClick={nextMonth}
        >
         <IoChevronForward className={["[font-size:0.95rem]"].filter(Boolean).join(" ")} />
        </button>
       </div>

       {/* Day labels */}
       <div
        className={["grid", "[grid-template-columns:repeat(7,_1fr)]", "[margin-bottom:6px]"].filter(Boolean).join(" ")}
       >
        {DAYS.map((d) => (
         <div
          key={d}
          className={["text-center", "[font-size:0.7rem]", "[800]", "[text-transform:uppercase]", "[letter-spacing:0.05em]", "[color:var(--tl)]", "[padding-bottom:4px]"].filter(Boolean).join(" ")}
         >
          {d}
         </div>
        ))}
       </div>

       {/* Day cells */}
       <div
        className={["grid", "[grid-template-columns:repeat(7,_1fr)]", "gap-0.5"].filter(Boolean).join(" ")}
       >
        {cells.map((cell, i) => (
         <div
          key={i}
          className={["flex", "justify-center"].filter(Boolean).join(" ")}
         >
          <button
           type="button"
           disabled={isDisabledDay(cell)}
           className={`dtp-day-btn ${cell.outside ? "outside" : ""} ${isToday(cell) && !isSelected(cell) ? "today" : ""} ${isSelected(cell) ? "selected" : ""}`}
           onClick={() => !isDisabledDay(cell) && selectDay(cell)}
          >
           {cell.day}
          </button>
         </div>
        ))}
       </div>

       {showTime && (
        <p
         className={["text-center", "[font-size:0.72rem]", "[color:var(--tl)]", "[margin-top:12px]", "[600]"].filter(Boolean).join(" ")}
        >
         Select a date, then set the time →
        </p>
       )}
      </>
     )}

     {dateView === "month" && (
      <>
       <div
        className={["flex", "items-center", "justify-between", "[margin-bottom:14px]"].filter(Boolean).join(" ")}
       >
        <button
         type="button"
         className="dtp-nav-btn"
         onClick={() => setDateView("calendar")}
        >
         <IoChevronBack className={["[font-size:0.95rem]"].filter(Boolean).join(" ")} />
        </button>
        <span
         className={["[800]", "[font-size:0.95rem]", "[color:var(--tp)]"].filter(Boolean).join(" ")}
        >
         Select Month
        </span>
        <div className={["w-8"].filter(Boolean).join(" ")}></div>
       </div>
       <div
        
        className="dtp-grid-container [height:250px] [grid-template-rows:repeat(4,_1fr)]"
       >
        {MONTHS.map((m, i) => (
         <button
          type="button"
          key={m}
          disabled={isMonthDisabled(i)}
          className={`dtp-grid-btn ${i === viewMonth ? "active" : ""}`}
          onClick={() => {
           if (!isMonthDisabled(i)) {
            setViewMonth(i);
            setDateView("calendar");
           }
          }}
         >
          {m.slice(0, 3)}
         </button>
        ))}
       </div>
      </>
     )}

     {dateView === "year" && (
      <>
       <div
        className={["flex", "items-center", "justify-between", "[margin-bottom:14px]"].filter(Boolean).join(" ")}
       >
        <button
         type="button"
         className="dtp-nav-btn"
         onClick={() => setDateView("calendar")}
        >
         <IoChevronBack className={["[font-size:0.95rem]"].filter(Boolean).join(" ")} />
        </button>
        <span
         className={["[800]", "[font-size:0.95rem]", "[color:var(--tp)]"].filter(Boolean).join(" ")}
        >
         Select Year
        </span>
        <div className={["w-8"].filter(Boolean).join(" ")}></div>
       </div>
       <div
        className="dtp-grid-container dtp-year-scroll"
        ref={yearScrollRef}
       >
        {Array.from({ length: 201 }, (_, i) => 1900 + i).map((y) => (
         <button
          type="button"
          key={y}
          disabled={isYearDisabled(y)}
          className={`dtp-grid-btn ${y === viewYear ? "active" : ""}`}
          onClick={() => {
           if (!isYearDisabled(y)) {
            setViewYear(y);
            setDateView("calendar");
           }
          }}
         >
          {y}
         </button>
        ))}
       </div>
      </>
     )}
    </div>
   )}

   {/* Time Panel */}
   {(tab === "time" || timeOnly) && (showTime || timeOnly) && (
    <div className={["p-4", "[height:340px]", "[overflow:hidden]"].filter(Boolean).join(" ")}>
     {/* Header: big clock + format toggle */}
     <div
      className={["flex", "items-center", "justify-between", "[margin-bottom:14px]"].filter(Boolean).join(" ")}
     >
      {/* Big time display */}
      <span
       className={["[font-size:2.4rem]", "[900]", "[color:var(--p)]", "[letter-spacing:-0.02em]", "[1]", "[font-variant-numeric:tabular-nums]"].filter(Boolean).join(" ")}
      >
       {is24h ? pad(hour) : pad(to12h(hour))}
       <span className={["[0.35]", "[margin:0_2px]"].filter(Boolean).join(" ")}>:</span>
       {pad(minute)}
       {!is24h && (
        <span
         className={["text-base", "[800]", "[margin-left:6px]", "[color:var(--ts)]"].filter(Boolean).join(" ")}
        >
         {hour >= 12 ? "PM" : "AM"}
        </span>
       )}
      </span>

      {/* 12h / 24h toggle */}
      <div className="dtp-format-toggle">
       <button
        type="button"
        className={`dtp-format-btn ${!is24h ? "active" : ""}`}
        onClick={() => setIs24h(false)}
       >
        12H
       </button>
       <button
        type="button"
        className={`dtp-format-btn ${is24h ? "active" : ""}`}
        onClick={() => setIs24h(true)}
       >
        24H
       </button>
      </div>
     </div>

     {/* Columns: Hour | Minute | (AM/PM if 12h) */}
     <div
      className={["grid", (is24h) ? "[grid-template-columns:1fr_1fr]" : "[grid-template-columns:1fr_1fr_46px]", "[gap:10px]"].filter(Boolean).join(" ")}
     >
      {/* Hour */}
      <div>
       <p
        className={["text-center", "[font-size:0.68rem]", "[700]", "[text-transform:uppercase]", "[letter-spacing:0.06em]", "[color:var(--tl)]", "[margin-bottom:6px]"].filter(Boolean).join(" ")}
       >
        Hour
       </p>
       <div className="dtp-time-scroll" ref={hourScrollRef}>
        {hourList.map((h) => {
         const h24 = is24h ? h : resolve24h(h, ampm);
         const disabledHour =
          isHourDisabled(h24) || !hasSelectableMinute(h24);
         const active24 = is24h ? h === hour : to12h(hour) === h;
         return (
          <div
           key={h}
           className={`dtp-time-item ${active24 ? "active" : ""} ${disabledHour ? "disabled" : ""}`}
           onClick={() => {
            if (disabledHour) return;
            const nextH = is24h ? h : resolve24h(h, ampm);
            const nextM = isMinuteDisabled(minute, nextH)
             ? (firstEnabledMinute(nextH) ?? minute)
             : minute;
            setHour(nextH);
            setMinute(nextM);
            emit(selectedDate, nextH, nextM);
           }}
          >
           {pad(h)}
          </div>
         );
        })}
       </div>
      </div>

      {/* Minute */}
      <div>
       <p
        className={["text-center", "[font-size:0.68rem]", "[700]", "[text-transform:uppercase]", "[letter-spacing:0.06em]", "[color:var(--tl)]", "[margin-bottom:6px]"].filter(Boolean).join(" ")}
       >
        Min
       </p>
       <div className="dtp-time-scroll" ref={minScrollRef}>
        {MINUTE_LIST.map((m) => {
         const disabledMin = isMinuteDisabled(m);
         return (
          <div
           key={m}
           className={`dtp-time-item ${m === minute ? "active" : ""} ${disabledMin ? "disabled" : ""}`}
           onClick={() => {
            if (disabledMin) return;
            setMinute(m);
            emit(selectedDate, hour, m);
           }}
          >
           {pad(m)}
          </div>
         );
        })}
       </div>
      </div>

      {/* AM / PM column (12h only) */}
      {!is24h && (
       <div>
        <p
         className={["text-center", "[font-size:0.68rem]", "[700]", "[text-transform:uppercase]", "[letter-spacing:0.06em]", "[color:var(--tl)]", "[margin-bottom:6px]"].filter(Boolean).join(" ")}
        >
         &nbsp;
        </p>
        <div
         className={["flex", "flex-col", "gap-2", "[height:180px]", "justify-center"].filter(Boolean).join(" ")}
        >
         {["AM", "PM"].map((period) => {
          const disabledPeriod = isPeriodDisabled(period);
          return (
           <button
            type="button"
            key={period}
            disabled={disabledPeriod}
            className={`dtp-ampm-btn ${(period === "AM" ? hour < 12 : hour >= 12) ? "active" : ""}`}
            onClick={() => {
             if (disabledPeriod) return;
             setAmpm(period);
             const resolved = resolve24h(to12h(hour), period);
             let validHour = resolved;
             if (
              isHourDisabled(validHour) ||
              !hasSelectableMinute(validHour)
             ) {
              const startH = period === "AM" ? 0 : 12;
              for (let h = startH; h < startH + 12; h++) {
               if (
                !isHourDisabled(h) &&
                hasSelectableMinute(h)
               ) {
                validHour = h;
                break;
               }
              }
             }
             const validMinute = isMinuteDisabled(
              minute,
              validHour,
             )
              ? (firstEnabledMinute(validHour) ?? minute)
              : minute;
             setHour(validHour);
             setMinute(validMinute);
             emit(selectedDate, validHour, validMinute);
            }}
           >
            {period}
           </button>
          );
         })}
        </div>
       </div>
      )}
     </div>

     <button
      type="button"
      onClick={confirmTime}
      className={["[margin-top:14px]", "w-full", "[padding:10px]", "[background:var(--p)]", "[color:var(--bgs)]", "border-0", "[border-radius:8px]", "[font-size:0.88rem]", "[800]", "[letter-spacing:0.04em]", "cursor-pointer", "[transition:opacity_0.15s]"].filter(Boolean).join(" ")}
     >
      Confirm
     </button>
    </div>
   )}
  </div>
 );

 return (
  <div
   className={["dtp-root [position:relative] [display:inline-block] [width:100%]", open ? "[z-index:999]" : "[z-index:1]"].filter(Boolean).join(" ")}
   ref={wrapperRef}
  >
   {label && (
    <label
     className={`block font-semibold mb-2 ${
      isInvalid ? "text-(--danger)" : "text-(--ts)"
     } ${
      size === "sm"
       ? "text-[11px]"
       : size === "md"
        ? "text-[13px]"
        : size === "lg"
         ? "text-[13.5px]"
         : "text-[15px]"
     }`}
     htmlFor={pickerId}
    >
     {label}
     {isRequired && (
      <span className={["[color:var(--red-500)]", "[margin-left:4px]"].filter(Boolean).join(" ")}>
       *
      </span>
     )}
    </label>
   )}

   {/* Trigger */}
   <div ref={triggerRef} className={["w-full"].filter(Boolean).join(" ")}>
    {customTrigger ? (
     <div
      onClick={() => !disabled && setOpen((o) => !o)}
      className={[(disabled) ? "cursor-not-allowed" : "cursor-pointer"].filter(Boolean).join(" ")}
     >
      {customTrigger}
     </div>
    ) : (
     <button
      type="button"
      id={pickerId}
      disabled={disabled}
      onClick={() => !disabled && setOpen((o) => !o)}
      className={[
       "flex w-full items-center gap-2.5 text-left outline-none font-medium transition-[border-color_0.18s,background_0.18s,box-shadow_0.18s]",
       size === "sm"
        ? "h-8 px-3 rounded-xl text-xs"
        : size === "md"
         ? "h-10 px-4 rounded-2xl text-sm"
         : size === "lg"
          ? "h-12 px-4 rounded-2xl text-sm"
          : "h-14 px-5 rounded-2xl text-base",
       disabled ? "opacity-50 cursor-not-allowed" : "cursor-pointer",
       isInvalid ? "[border-width:1.5px] border-(--danger)" : open ? "[border-width:1.5px] border-(--p)" : "[border-width:1.5px] border-(--bd2)",
       open ? "bg-(--pale)" : "bg-(--bgs)",
       open ? "[box-shadow:0_0_0_4px_var(--pale)]" : "",
       displayValue() ? "text-(--tp)" : "text-(--tl)",
      ].filter(Boolean).join(" ")}
     >
      {timeOnly ? (
       <IoTimeOutline
        className={["[color:var(--p)]", (size === "sm") ? "[font-size:0.95rem]" : (size === "md" || size === "lg") ? "[font-size:1.1rem]" : "text-xl", "[0]"].filter(Boolean).join(" ")}
       />
      ) : (
       <IoCalendarOutline
        className={["[color:var(--p)]", (size === "sm") ? "[font-size:0.95rem]" : (size === "md" || size === "lg") ? "[font-size:1.1rem]" : "text-xl", "[0]"].filter(Boolean).join(" ")}
       />
      )}
      <span className={["[1]", "[overflow:hidden]", "[text-overflow:ellipsis]", "whitespace-nowrap"].filter(Boolean).join(" ")}>
       {displayValue() ?? placeholder}
      </span>
      {selectedDate && !disabled && (
       <span
        role="button"
        tabIndex={0}
        onKeyDown={(e) =>
         e.key === "Enter" &&
         (e.stopPropagation(), setSelectedDate(null), onChange?.(""))
        }
        onClick={(e) => {
         e.stopPropagation();
         setSelectedDate(null);
         onChange?.("");
        }}
        className={["[color:var(--tl)]", "[1]", "cursor-pointer"].filter(Boolean).join(" ")}
       >
        <IoClose className={["text-base"].filter(Boolean).join(" ")} />
       </span>
      )}
     </button>
    )}
   </div>

   {/* Dropdown via Portal */}
   {open &&
    typeof document !== "undefined" &&
    createPortal(dropdownContent, document.body)}

   {isInvalid && errorMessage && (
    <div className="mt-1.5 text-xs text-(--danger)" role="alert">
     {errorMessage}
    </div>
   )}
  </div>
 );
}

"use client";

import React, { useMemo } from "react";
import { FiCheck, FiShield, FiAlertCircle } from "react-icons/fi";

/**
 * Calculates password strength and returns score (0-4), status, and checks.
 */
export function getPasswordStrength(password = "") {
 const pwd = String(password || "");

 const checks = [
  {
   id: "length",
   label: "At least 8 characters",
   met: pwd.length >= 8,
  },
  {
   id: "uppercase",
   label: "At least 1 uppercase letter (A-Z)",
   met: /[A-Z]/.test(pwd),
  },
  {
   id: "lowercase",
   label: "At least 1 lowercase letter (a-z)",
   met: /[a-z]/.test(pwd),
  },
  {
   id: "number",
   label: "At least 1 number (0-9)",
   met: /[0-9]/.test(pwd),
  },
  {
   id: "special",
   label: "At least 1 special symbol (!@#$%^&*)",
   met: /[^A-Za-z0-9]/.test(pwd),
  },
 ];

 const metCount = checks.filter((c) => c.met).length;

 // Derive score from 0 to 4
 let score = 0;
 if (pwd.length === 0) {
  score = 0;
 } else if (pwd.length < 6) {
  score = 1; // Very short
 } else if (metCount <= 2) {
  score = 1;
 } else if (metCount === 3) {
  score = 2;
 } else if (metCount === 4) {
  score = 3;
 } else if (metCount === 5) {
  score = 4;
 }

 // Bonus for 12+ chars if at least 3 criteria met
 if (pwd.length >= 12 && metCount >= 4) {
  score = 4;
 }

 const levels = [
  {
   label: "Too weak",
   color: "bg-(--bgl) dark:bg-(--bgl)",
   textColor: "text-(--tl)",
   pillBg: "bg-(--bgm) dark:bg-(--bgm) text-(--tm)",
  },
  {
   label: "Weak",
   color: "bg-(--danger-bg)0",
   textColor: "text-(--danger)",
   pillBg:
    "bg-(--danger-bg) dark:bg-(--danger-bg) text-(--danger) border border-(--danger) dark:border-(--bd)-red-900/50",
  },
  {
   label: "Fair",
   color: "bg-(--warning-bg)0",
   textColor: "text-(--warning)",
   pillBg:
    "bg-(--warning-bg) dark:bg-(--warning-bg) text-(--warning) border border-(--warning) dark:border-(--bd)-(--warning)",
  },
  {
   label: "Good",
   color: "bg-(--info)",
   textColor: "text-(--info)",
   pillBg:
    "bg-(--info-bg) dark:bg-(--info-bg) text-(--info) border border-(--info) dark:border-(--bd)-(--info)",
  },
  {
   label: "Strong",
   color: "bg-(--success)",
   textColor: "text-(--success)",
   pillBg:
    "bg-(--success-bg) dark:bg-(--success-bg) text-(--success) border border-(--success) dark:border-(--bd)-(--success)",
  },
 ];

 const currentLevel = levels[score] || levels[0];

 // Actionable suggestions
 const unmetChecks = checks.filter((c) => !c.met);
 let suggestion = "";
 if (pwd.length === 0) {
  suggestion =
   "Enter a strong password with a mix of letters, numbers & symbols.";
 } else if (unmetChecks.length > 0) {
  const firstMissing = unmetChecks[0];
  suggestion = `Suggestion: ${firstMissing.label.replace("At least 1 ", "Add a ")}.`;
 } else {
  suggestion = "Great! Your password is strong and secure.";
 }

 return {
  score, // 0 to 4
  level: currentLevel,
  checks,
  unmetChecks,
  suggestion,
  isStrong: score >= 3,
 };
}

/**
 * Reusable PasswordStrengthMeter component
 */
export default function PasswordStrengthMeter({
 password = "",
 showSuggestions = true,
 compact = false,
 className = "",
}) {
 const { score, level, checks, suggestion, isStrong } = useMemo(
  () => getPasswordStrength(password),
  [password],
 );

 const hasInput = Boolean(password && password.length > 0);

 return (
  <div
   className={`space-y-2 mt-2 w-full transition-all duration-200 ${className}`}
  >
   {/* Meter Bar and Score Label */}
   <div className="flex items-center justify-between gap-3">
    <div className="flex-1 flex gap-1.5 h-1.5 rounded-full overflow-hidden bg-(--bgm) dark:bg-(--bgm) p-0.5">
     {[1, 2, 3, 4].map((step) => {
      const isFilled = hasInput && score >= step;
      return (
       <div
        key={step}
        className={`flex-1 h-full rounded-full transition-all duration-300 ${
         isFilled ? level.color : "bg-(--bgl) dark:bg-(--bgl)/60"
        }`}
       />
      );
     })}
    </div>

    {hasInput && (
     <span
      className={`text-[11px] font-bold px-2 py-0.5 rounded-md transition-all shrink-0 ${level.pillBg}`}
     >
      {level.label}
     </span>
    )}
   </div>

   {/* Live Suggestions & Requirements */}
   {showSuggestions && hasInput && (
    <div className="rounded-xl border border-(--bd2) bg-(--bgl)/40 p-2.5 sm:p-3 space-y-2 text-xs">
     {/* Actionable tip banner */}
     <div className="flex items-center gap-1.5 text-[11.5px]">
      {isStrong ? (
       <FiShield className="w-3.5 h-3.5 text-(--success) shrink-0" />
      ) : (
       <FiAlertCircle className="w-3.5 h-3.5 text-(--warning) shrink-0" />
      )}
      <span
       className={`font-medium truncate ${
        isStrong
         ? "text-(--success) dark:text-(--success)"
         : "text-(--warning) dark:text-(--warning)"
       }`}
      >
       {suggestion}
      </span>
     </div>

     {!compact && (
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-2 gap-y-1 pt-1 border-t border-(--bd2)/60 text-[11px]">
       {checks.map((check) => (
        <div
         key={check.id}
         className={`flex items-center gap-1.5 transition-colors ${
          check.met
           ? "text-(--success) dark:text-(--success) font-medium"
           : "text-(--tm)/70"
         }`}
        >
         {check.met ? (
          <FiCheck className="w-3 h-3 text-(--success) shrink-0 stroke-[2.5]" />
         ) : (
          <span className="w-1.5 h-1.5 rounded-full bg-(--tm)/40 shrink-0 ml-0.5 mr-1" />
         )}
         <span className="truncate">{check.label}</span>
        </div>
       ))}
      </div>
     )}
    </div>
   )}
  </div>
 );
}

"use client";

import React, {
 forwardRef,
 useState,
 useEffect,
 useRef,
 useCallback,
} from "react";
import { createPortal } from "react-dom";
import flags from "react-phone-number-input/flags";
import { LuChevronDown } from "react-icons/lu";

function CountryFlag({ country, label }) {
 const iso = country ? String(country).toUpperCase() : "";
 const Flag = iso ? flags[iso] : null;
 if (!Flag) {
  return (
   <span className="phone-country-empty-flag" aria-hidden="true">
    --
   </span>
  );
 }

 return (
  <span className="phone-country-flag shrink-0" aria-hidden="true">
   <Flag title={label || iso} />
  </span>
 );
}

const Select = forwardRef(
 (
  {
   variant = "outline",
   size = "md",
   isInvalid = false,
   isDisabled = false,
   isBlocked = false,
   isRequired = false,
   options = [],
   placeholder,
   errorMessage,
   helperText,
   label,
   align = "top",
   labelWidth: propLabelWidth,
   inputWidth: propInputWidth,
   className = "",
   id,
   isSearchable = false,
   inputValue: externalInputValue,
   onInputChange,
   isLoading = false,
   displayValue: propDisplayValue,
   leftElement: _leftElement,
   ...props
  },
  ref,
 ) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const initialSelected = options.find(
   (option) =>
    String(option.value) === String(props.value) ||
    String(option.label).toLowerCase() ===
     String(props.value).toLowerCase() ||
    (option.iso &&
     String(option.iso).toUpperCase() ===
      String(props.value).toUpperCase()),
  );
  const [selectedOption, setSelectedOption] = useState(props.value || "");
  const [displayValue, setDisplayValue] = useState(
   propDisplayValue || initialSelected?.label || "",
  );
  const [dropdownPosition, setDropdownPosition] = useState({
   top: 0,
   left: 0,
   width: 0,
  });

  const selectContainerRef = useRef(null);
  const searchInputRef = useRef(null);
  const buttonRef = useRef(null);
  const dropdownRef = useRef(null);
  const prevValueRef = useRef(undefined);
  const prevOptionsRef = useRef(undefined);

  // Auto-detect if this select has flags or is a country field
  const hasFlags = options.some((opt) => Boolean(opt?.iso));
  const isCountryField =
   (props.name && String(props.name).toLowerCase().includes("country")) ||
   (label && String(label).toLowerCase().includes("country"));
  const shouldUseSearchable = isSearchable || hasFlags || isCountryField;

  // Handle automatic width calculation for labelWidth and inputWidth
  let labelWidth = propLabelWidth || "30%";
  let inputWidth = propInputWidth || "70%";

  if (propLabelWidth && !propInputWidth) {
   if (propLabelWidth.endsWith("%")) {
    const labelPercentage = parseFloat(propLabelWidth);
    if (!isNaN(labelPercentage)) {
     inputWidth = `${100 - labelPercentage}%`;
    }
   }
  } else if (!propLabelWidth && propInputWidth) {
   if (propInputWidth.endsWith("%")) {
    const inputPercentage = parseFloat(propInputWidth);
    if (!isNaN(inputPercentage)) {
     labelWidth = `${100 - inputPercentage}%`;
    }
   }
  }

  const selectId =
   id || `select-${Math.random().toString(36).substring(2, 9)}`;

  // Handle controlled input value from parent component
  useEffect(() => {
   if (externalInputValue !== undefined) {
    setSearchTerm(externalInputValue);
   }
  }, [externalInputValue]);

  // Filter options based on search term (searches label, value, ISO and calling code)
  const filteredOptions = options.filter((option) => {
   const term = searchTerm.trim().toLowerCase();
   if (!term) return true;
   return (
    option.label?.toLowerCase().includes(term) ||
    String(option.value)?.toLowerCase().includes(term) ||
    (option.iso && String(option.iso).toLowerCase().includes(term)) ||
    (option.code && String(option.code).toLowerCase().includes(term))
   );
  });

  // Update dropdown position on open, scroll, or resize
  const updateDropdownPosition = useCallback(() => {
   if (buttonRef.current) {
    const rect = buttonRef.current.getBoundingClientRect();
    const width = Math.max(rect.width, 280);
    let left = rect.left;
    if (
     typeof window !== "undefined" &&
     left + width > window.innerWidth - 16
    ) {
     left = Math.max(12, window.innerWidth - width - 16);
    }
    setDropdownPosition({
     top: rect.bottom + 4,
     left,
     width,
    });
   }
  }, []);

  // Handle click outside and Escape
  useEffect(() => {
   if (!isOpen) return undefined;

   const handleClickOutside = (event) => {
    const insideSelect = selectContainerRef.current?.contains(event.target);
    const insideDropdown = dropdownRef.current?.contains(event.target);

    if (!insideSelect && !insideDropdown) {
     setIsOpen(false);
     setSearchTerm("");
     if (props.onBlur) {
      props.onBlur({
       target: {
        name: props.name || "",
        value: selectedOption,
       },
      });
     }
    }
   };

   const handleEscape = (event) => {
    if (event.key === "Escape") {
     setIsOpen(false);
     setSearchTerm("");
    }
   };

   updateDropdownPosition();
   document.addEventListener("mousedown", handleClickOutside);
   document.addEventListener("keydown", handleEscape);
   window.addEventListener("scroll", updateDropdownPosition, true);
   window.addEventListener("resize", updateDropdownPosition);
   requestAnimationFrame(() => searchInputRef.current?.focus());

   return () => {
    document.removeEventListener("mousedown", handleClickOutside);
    document.removeEventListener("keydown", handleEscape);
    window.removeEventListener("scroll", updateDropdownPosition, true);
    window.removeEventListener("resize", updateDropdownPosition);
   };
  }, [isOpen, updateDropdownPosition, props.onBlur, props.name, selectedOption]);

  // Update display value when selected value or options change
  useEffect(() => {
   const optionsChanged =
    JSON.stringify(prevOptionsRef.current) !== JSON.stringify(options);
   const valueChanged = prevValueRef.current !== props.value;

   if (!valueChanged && !optionsChanged) {
    return;
   }

   prevValueRef.current = props.value;
   prevOptionsRef.current = options;

   const selected = options.find(
    (option) =>
     String(option.value) === String(props.value) ||
     String(option.label).toLowerCase() ===
      String(props.value).toLowerCase() ||
     (option.iso &&
      String(option.iso).toUpperCase() ===
       String(props.value).toUpperCase()),
   );

   const newSelectedValue = props.value || "";
   let newDisplayValue = "";

   if (propDisplayValue) {
    newDisplayValue = propDisplayValue;
   } else if (selected) {
    newDisplayValue = selected.label;
   } else {
    newDisplayValue = "";
   }

   setSelectedOption(newSelectedValue);
   setDisplayValue(newDisplayValue);

   if (externalInputValue === undefined) {
    setSearchTerm("");
   }
  }, [options, props.value, externalInputValue, propDisplayValue]);

  // Handle search input change
  const handleSearchInputChange = (e) => {
   e.stopPropagation();
   const value = e.target.value;
   setSearchTerm(value);
   if (onInputChange) {
    onInputChange(value);
   }
  };

  // Handle option selection
  const handleOptionSelect = (option) => {
   if (option.disabled) {
    return;
   }

   const syntheticEvent = {
    target: {
     name: props.name || "",
     value: option.value,
    },
    preventDefault: () => {},
    stopPropagation: () => {},
   };

   if (props.onChange) {
    props.onChange(syntheticEvent);
   }

   setSelectedOption(option.value);
   setDisplayValue(option.label);
   setSearchTerm("");
   setIsOpen(false);
  };

  // Toggle dropdown
  const toggleDropdown = (e) => {
   e.preventDefault();
   e.stopPropagation();
   if (!isDisabled && !isBlocked) {
    const newIsOpen = !isOpen;
    setIsOpen(newIsOpen);
    if (newIsOpen) {
     setSearchTerm("");
     updateDropdownPosition();
    }
   }
  };

  // Base select classes
  const baseClasses = "w-full transition-all duration-200 focus:outline-none";

  const sizeClasses = {
   sm: "h-8 text-xs px-3 rounded-xl",
   md: "h-10 text-sm px-4 rounded-2xl",
   lg: "h-12 text-sm px-4 rounded-2xl",
   xl: "h-14 text-base px-5 rounded-2xl",
  };

  // Variant classes matching Input.jsx
  const variantClasses = {
   outline:
    "border-[1.5px] border-(--bd2) bg-(--bgs) focus:border-(--p) focus:ring-4 focus:ring-(--pale) text-(--tp) hover:border-(--p)/50 transition-colors",
   filled:
    "border-[1.5px] border-transparent bg-(--bgm) focus:bg-(--bgs) focus:border-(--p) focus:ring-4 focus:ring-(--pale) text-(--tp) hover:bg-(--bd) transition-colors",
   flushed:
    "border-b-[1.5px] border-(--bd2) rounded-none px-0 bg-transparent focus:border-b-(--p) text-(--tp) focus:ring-0 focus:ring-offset-0 transition-colors",
  };

  const stateClasses = {
   invalid: "border-(--danger)! focus:border-(--danger)! focus:ring-(--danger)/20!",
   disabled: "opacity-60 cursor-not-allowed bg-(--bgs)",
   blocked: "opacity-70 cursor-not-allowed bg-(--bgs) pointer-events-none",
  };

  const labelClasses = {
   base: "block text-(--ts) font-semibold",
   sm: "text-xs",
   md: "text-[13px]",
   lg: "text-[13.5px]",
   xl: "text-[15px]",
   disabled: "opacity-60",
   blocked: "opacity-70",
   invalid: "text-(--danger)",
   top: "mb-2",
   bottom: "mt-2",
   left: "mr-3",
   right: "ml-3",
  };

  const helperTextClasses = "mt-1.5 text-xs text-(--tm)";
  const errorMessageClasses =
   "mt-1.5 text-xs text-(--danger) flex items-center gap-1 font-medium";
  const placeholderClass = "placeholder:text-(--tl)";

  const selectButtonClasses = [
   baseClasses,
   variantClasses[variant] || variantClasses.outline,
   sizeClasses[size] || sizeClasses.md,
   placeholderClass,
   "flex items-center justify-between cursor-pointer relative appearance-none text-left font-normal",
   isOpen ? "border-(--p) ring-4 ring-(--pale)" : "",
   isInvalid ? stateClasses.invalid : "",
   isDisabled ? stateClasses.disabled : "",
   isBlocked ? stateClasses.blocked : "",
   className,
  ].join(" ");

  const labelClassNames = [
   labelClasses.base,
   labelClasses[size],
   labelClasses[align],
   isDisabled ? labelClasses.disabled : "",
   isBlocked ? labelClasses.blocked : "",
   isInvalid ? labelClasses.invalid : "",
  ].join(" ");

  const labelElement = (
   <label htmlFor={selectId} className={labelClassNames}>
    {label}
    {isRequired && <span className="text-(--danger) ml-1">*</span>}
   </label>
  );

  // Selected option object (used for flag resolution)
  const selectedOptionObj = options.find(
   (opt) =>
    String(opt.value) === String(selectedOption) ||
    String(opt.label).toLowerCase() ===
     String(selectedOption).toLowerCase() ||
    (opt.iso &&
     String(opt.iso).toUpperCase() === String(selectedOption).toUpperCase()),
  );

  // Hidden select for standard form serialization
  const renderHiddenSelect = () => (
   <select
    ref={ref}
    id={selectId}
    className="hidden"
    aria-hidden="true"
    value={selectedOption}
    onChange={() => {}}
    disabled={isDisabled || isBlocked}
    required={isRequired}
    {...props}
   >
    {placeholder && (
     <option value="" disabled hidden>
      {placeholder}
     </option>
    )}
    {options.map((option) => (
     <option
      key={option.value}
      value={option.value}
      disabled={option.disabled}
     >
      {option.label}
     </option>
    ))}
   </select>
  );

  // Regular select (not searchable)
  const regularSelectContent = (
   <div className="relative">
    <select
     ref={ref}
     id={selectId}
     className={[
      baseClasses,
      variantClasses[variant],
      sizeClasses[size],
      placeholderClass,
      isInvalid ? stateClasses.invalid : "",
      isDisabled ? stateClasses.disabled : "",
      isBlocked ? stateClasses.blocked : "",
      "appearance-none pr-8",
      className,
     ].join(" ")}
     aria-invalid={isInvalid}
     aria-describedby={
      helperText
       ? `${selectId}-helper-text`
       : errorMessage && isInvalid
        ? `${selectId}-error-message`
        : undefined
     }
     disabled={isDisabled || isBlocked}
     required={isRequired}
     {...props}
    >
     {placeholder && (
      <option value="" disabled hidden>
       {placeholder}
      </option>
     )}
     {options.map((option) => (
      <option
       key={option.value}
       value={option.value}
       disabled={option.disabled}
      >
       {option.label}
      </option>
     ))}
    </select>

    <div className="absolute inset-y-0 right-0 flex items-center px-3 pointer-events-none">
     <LuChevronDown className="w-4 h-4 text-(--tl)" />
    </div>
   </div>
  );

  // Searchable select content matching the phone country selector
  const searchableSelectContent = (
   <div
    
    ref={selectContainerRef}
    className="relative w-full [position:relative]"
   >
    {renderHiddenSelect()}

    <button
     type="button"
     ref={buttonRef}
     id={selectId}
     role="combobox"
     disabled={isDisabled || isBlocked}
     onClick={toggleDropdown}
     className={selectButtonClasses}
     aria-haspopup="listbox"
     aria-expanded={isOpen}
     aria-controls={`${selectId}-menu`}
     aria-invalid={isInvalid}
     aria-describedby={
      helperText
       ? `${selectId}-helper-text`
       : errorMessage && isInvalid
        ? `${selectId}-error-message`
        : undefined
     }
    >
     <span className="flex items-center gap-2.5 min-w-0 flex-1">
      {selectedOptionObj?.iso ? (
       <CountryFlag
        country={selectedOptionObj.iso}
        label={selectedOptionObj.label}
       />
      ) : null}
      <span
       className={`truncate ${
        !selectedOption && placeholder ? "text-(--tl)" : "text-(--tp)"
       }`}
      >
       {displayValue || placeholder || "Select option"}
      </span>
     </span>

     <span className="flex items-center gap-1.5 shrink-0 ml-2">
      {isLoading && (
       <div className="animate-spin h-4 w-4 border-2 border-(--p) border-t-transparent rounded-full" />
      )}
      <LuChevronDown
       className={`w-4 h-4 text-(--tl) transition-transform duration-200 ${isOpen ? "rotate-180" : ""}`}
      />
     </span>
    </button>

    {/* Dropdown menu - Portal to body matching phone-country-menu */}
    {isOpen &&
     typeof document !== "undefined" &&
     createPortal(
      <div
       ref={dropdownRef}
       id={`${selectId}-menu`}
       
       className="phone-country-menu [position:fixed] [top:var(--inline-top)] [left:var(--inline-left)] [width:var(--inline-width)] [max-width:calc(100vw_-_2rem)] [100000]" style={{ "--inline-top": dropdownPosition.top, "--inline-left": dropdownPosition.left, "--inline-width": dropdownPosition.width }}
       role="listbox"
       onClick={(e) => e.stopPropagation()}
      >
       {/* Search input with phone-country-search styling */}
       <input
        ref={searchInputRef}
        type="text"
        className="phone-country-search"
        placeholder={
         isCountryField || hasFlags ? "Search country..." : "Search..."
        }
        value={searchTerm}
        onChange={handleSearchInputChange}
        onClick={(e) => e.stopPropagation()}
        onKeyDown={(e) => {
         e.stopPropagation();
         if (e.key === "Escape") {
          setIsOpen(false);
          setSearchTerm("");
         }
         if (e.key === "Enter" && filteredOptions.length > 0) {
          e.preventDefault();
          handleOptionSelect(filteredOptions[0]);
         }
        }}
       />

       {/* Options list with phone-country-options styling */}
       <div className="phone-country-options">
        {filteredOptions.length > 0 ? (
         filteredOptions.map((option) =>
          option.disabled ? (
           <div
            key={option.value}
            className="phone-country-option opacity-50 cursor-not-allowed"
            role="option"
            aria-selected={
             String(option.value) === String(selectedOption)
            }
            aria-disabled="true"
            title={`${option.label} is disabled`}
           >
            {option.iso && (
             <CountryFlag
              country={option.iso}
              label={option.label}
             />
            )}
            <span className="phone-country-option-label">
             {option.label}
            </span>
            <span className="text-[10px] font-semibold italic text-(--tm)">
             Disabled
            </span>
           </div>
          ) : (
           <button
            key={option.value}
            type="button"
            className={`phone-country-option ${
             String(option.value) === String(selectedOption)
              ? "is-selected"
              : ""
            }`}
            role="option"
            aria-selected={
             String(option.value) === String(selectedOption)
            }
            onClick={(e) => {
             e.stopPropagation();
             handleOptionSelect(option);
            }}
           >
            {option.iso && (
             <CountryFlag
              country={option.iso}
              label={option.label}
             />
            )}
            <span className="phone-country-option-label">
             {option.label}
            </span>
            {option.code && (
             <span className="phone-country-option-code">
              {option.code}
             </span>
            )}
           </button>
          ),
         )
        ) : (
         <div className="phone-country-empty">
          No results found for &quot;{searchTerm}&quot;
         </div>
        )}
       </div>
      </div>,
      document.body,
     )}
   </div>
  );

  const renderHelperAndError = () => (
   <>
    {helperText && !isInvalid && (
     <div id={`${selectId}-helper-text`} className={helperTextClasses}>
      {helperText}
     </div>
    )}

    {isInvalid && errorMessage && (
     <div id={`${selectId}-error-message`} className={errorMessageClasses}>
      {errorMessage}
     </div>
    )}
   </>
  );

  // Return the component JSX
  return (
   <div className="w-full">
    {label ? (
     <>
      {align === "top" && (
       <div className="flex flex-col">
        {labelElement}
        {shouldUseSearchable
         ? searchableSelectContent
         : regularSelectContent}
       </div>
      )}
      {align === "bottom" && (
       <div className="flex flex-col">
        {shouldUseSearchable
         ? searchableSelectContent
         : regularSelectContent}
        {labelElement}
       </div>
      )}
      {align === "left" && (
       <div className="flex items-center justify-between gap-4">
        <div className={["[width:var(--inline-width)]"].filter(Boolean).join(" ")} style={{ "--inline-width": labelWidth }}>{labelElement}</div>
        <div className={["[width:var(--inline-width)]"].filter(Boolean).join(" ")} style={{ "--inline-width": inputWidth }}>
         {shouldUseSearchable
          ? searchableSelectContent
          : regularSelectContent}
        </div>
       </div>
      )}
      {align === "right" && (
       <div className="flex items-center justify-between gap-4">
        <div className={["[width:var(--inline-width)]"].filter(Boolean).join(" ")} style={{ "--inline-width": inputWidth }}>
         {shouldUseSearchable
          ? searchableSelectContent
          : regularSelectContent}
        </div>
        <div className={["[width:var(--inline-width)]"].filter(Boolean).join(" ")} style={{ "--inline-width": labelWidth }}>{labelElement}</div>
       </div>
      )}
     </>
    ) : shouldUseSearchable ? (
     searchableSelectContent
    ) : (
     regularSelectContent
    )}
    {renderHelperAndError()}
   </div>
  );
 },
);

Select.displayName = "Select";

export default Select;

import React, {
 useRef,
 useEffect,
 useState,
 useMemo,
 useCallback,
 forwardRef,
 useImperativeHandle,
} from "react";
import {
 FiSearch,
 FiX,
 FiRefreshCw,
 FiDownload,
 FiEye,
 FiChevronDown,
 FiChevronUp,
 FiInbox,
 FiAlertCircle,
 FiFileText,
 FiFile,
} from "react-icons/fi";
import Button from "@/components/shared/Button";
import PaginationComponent from "@/components/shared/Pagination";
import Input from "@/components/shared/Input";
import Select from "@/components/shared/forms/Select";
import Checkbox from "@/components/shared/forms/Checkbox";
import DateTimePicker from "@/components/shared/ui/DateTimePicker";
import { parseRecordListResponse } from "@/lib/api/safeData";

const REFRESH_EVENT = "dashboard:refresh";
const REFRESH_START_EVENT = "dashboard:refresh:start";
const REFRESH_END_EVENT = "dashboard:refresh:end";

const getPaginationInfo = (response, defaultParams = {}) => {
 if (!response || typeof response !== "object") {
  return {
   page: defaultParams.page ?? 1,
   limit: defaultParams.limit ?? 10,
   totalItems: 0,
   totalPages: 1,
   sortBy: "",
   sortOrder: "",
  };
 }

 if (response?.pagination) {
  const page = Number(response.pagination.page ?? 1);
  const limit = Number(response.pagination.limit ?? 10);
  const totalItems = Number(
   response.pagination.totalItems ?? response.pagination.total ?? 0,
  );
  const totalPages =
   Math.ceil(totalItems / (limit || 1)) ||
   Number(response.pagination.totalPages ?? 1);
  return {
   page: isNaN(page) ? 1 : page,
   limit: isNaN(limit) ? 10 : limit,
   totalItems: isNaN(totalItems) ? 0 : totalItems,
   totalPages: isNaN(totalPages) ? 1 : totalPages,
   sortBy: response.pagination.sortBy ?? "",
   sortOrder: response.pagination.sortOrder ?? "",
  };
 }

 let dataArray = [];
 if (Array.isArray(response)) {
  dataArray = response;
 } else if (Array.isArray(response?.data)) {
  dataArray = response.data;
 } else if (Array.isArray(response?.data?.data)) {
  dataArray = response.data.data;
 } else if (response?.data && typeof response.data === "object") {
  const arrayKey = Object.keys(response.data).find((key) =>
   Array.isArray(response.data[key]),
  );
  if (arrayKey) {
   dataArray = response.data[arrayKey];
  }
 } else if (response && typeof response === "object") {
  const arrayKey = Object.keys(response).find((key) =>
   Array.isArray(response[key]),
  );
  if (arrayKey) {
   dataArray = response[arrayKey];
  }
 }

 const totalItems = Number(
  response?.pagination?.totalItems ??
  response?.pagination?.total ??
  response?.totalItems ??
  response?.total ??
  response?.data?.totalItems ??
  response?.data?.total ??
  response?.data?.pagination?.totalItems ??
  response?.data?.pagination?.total ??
  response?.count ??
  response?.data?.count ??
  dataArray.length,
 );
 const limit = Number(
  response?.pagination?.limit ??
  response?.limit ??
  response?.data?.limit ??
  response?.data?.pagination?.limit ??
  defaultParams.limit ??
  10,
 );
 const page = Number(
  response?.pagination?.page ??
  response?.page ??
  response?.data?.page ??
  response?.data?.pagination?.page ??
  defaultParams.page ??
  1,
 );
 const totalPages =
  Math.ceil(totalItems / (limit || 1)) ||
  Number(
   response?.pagination?.totalPages ??
   response?.totalPages ??
   response?.data?.totalPages ??
   response?.data?.pagination?.totalPages ??
   1,
  );

 return {
  page: isNaN(page) ? 1 : page,
  limit: isNaN(limit) ? 10 : limit,
  totalItems: isNaN(totalItems) ? 0 : totalItems,
  totalPages: isNaN(totalPages) ? 1 : totalPages,
  sortBy:
   response?.pagination?.sortBy ??
   response?.sortBy ??
   response?.data?.sortBy ??
   "",
  sortOrder:
   response?.pagination?.sortOrder ??
   response?.sortOrder ??
   response?.data?.sortOrder ??
   "",
 };
};

// SearchInput Component
export function SearchInput({
 value,
 onChange,
 placeholder = "Search...",
 disabled,
}) {
 return (
  <div className="relative flex-1 min-w-50 max-w-sm">
   <FiSearch
    className="absolute left-3 top-1/2 -translate-y-1/2 text-(--tm)"
    size={13}
   />
   <input
    type="text"
    placeholder={placeholder}
    disabled={disabled}
    value={value}
    onChange={onChange}
    className="w-full pl-9 pr-4 py-1.5 rounded-lg text-xs bg-(--bg) border border-(--bd) text-(--tp) placeholder:text-(--tl) focus:outline-none focus:border-(--p) transition-colors"
   />
  </div>
 );
}

// FilterBar Component
export function FilterBar({
 filters = [],
 activeParams = {},
 onFilterChange,
 disabled,
}) {
 return (
  <div className="flex items-center gap-2 flex-wrap">
   {filters.map((f) => (
    <select
     key={f.id}
     disabled={disabled}
     value={activeParams[f.id] || ""}
     onChange={(e) => onFilterChange(f.id, e.target.value)}
     className="px-2.5 py-1.5 rounded-lg text-xs bg-(--bg) border border-(--bd) text-(--tp) focus:outline-none focus:border-(--p) cursor-pointer"
    >
     <option value="">All {f.label}</option>
     {f.options.map((o) => (
      <option key={o.value} value={o.value}>
       {o.label}
      </option>
     ))}
    </select>
   ))}
  </div>
 );
}

// EmptyState Component
export function EmptyState({
 icon: Icon = FiInbox,
 title = "No data available",
 description = "There are no records to display.",
}) {
 return (
  <div className="flex flex-col items-center justify-center py-12 px-4 text-center">
   <div className="w-10 h-10 rounded-full bg-(--bgm) flex items-center justify-center text-(--tm) mb-3 border border-(--bd)">
    <Icon size={20} />
   </div>
   <h3 className="text-xs font-semibold text-(--tp)">{title}</h3>
   <p className="text-[11px] text-(--tm) mt-1 max-w-xs">{description}</p>
  </div>
 );
}

// ErrorState Component
export function ErrorState({ message = "Failed to load data", onRetry }) {
 return (
  <div className="flex flex-col items-center justify-center py-12 px-4 text-center">
   <div className="w-10 h-10 rounded-full bg-(--danger)/10 flex items-center justify-center text-(--danger) mb-3 border border-(--danger)/20">
    <FiAlertCircle size={20} />
   </div>
   <h3 className="text-xs font-semibold text-(--tp)">An Error Occurred</h3>
   <p className="text-[11px] text-(--tm) mt-1 max-w-xs">{message}</p>
   {onRetry && (
    <Button
     onClick={onRetry}
     variant="secondary"
     size="sm"
     className="mt-3"
     leftIcon={<FiRefreshCw size={12} />}
    >
     Retry
